@Composable
fun VerticalStack(modifier: Modifier = Modifier, content: @Composable () -> Unit) {
    Layout(content = content, modifier = modifier) { measurables, constraints ->
        val placeables = measurables.map { it.measure(constraints) }  // exactly once each
        val width = placeables.maxOfOrNull { it.width } ?: 0
        val height = placeables.sumOf { it.height }

        layout(width, height) {
            var y = 0
            placeables.forEach { p ->
                p.placeRelative(x = 0, y = y)
                y += p.height
            }
        }
    }
}

// Modifier.Node: element is the cheap comparable holder, node is long-lived
private data class PaddedElement(val all: Dp) : ModifierNodeElement<PaddedNode>() {
    override fun create() = PaddedNode(all)
    override fun update(node: PaddedNode) { node.all = all }   // no reallocation
}

private class PaddedNode(var all: Dp) : Modifier.Node(), LayoutModifierNode {
    override fun MeasureScope.measure(measurable: Measurable, constraints: Constraints): MeasureResult {
        val pad = all.roundToPx() * 2
        val placeable = measurable.measure(constraints.offset(-pad, -pad))
        return layout(placeable.width + pad, placeable.height + pad) {
            placeable.place(pad / 2, pad / 2)
        }
    }
}

fun Modifier.padded(all: Dp) = this then PaddedElement(all)

